import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;

import 'models.dart';

/// The bundled exercise library and plan templates
/// (assets/library/*.json, generated by tools/library/build_library.py).
class ExerciseLibrary {
  ExerciseLibrary(List<Exercise> exercises, this.templates)
    : byId = {for (final e in exercises) e.id: e},
      exercises = List.unmodifiable(exercises);

  final List<Exercise> exercises;
  final Map<String, Exercise> byId;
  final List<PlanTemplate> templates;

  Exercise operator [](String id) {
    final e = byId[id];
    if (e == null) throw ArgumentError('unknown exercise $id');
    return e;
  }

  bool has(String id) => byId.containsKey(id);

  PlanTemplate template(String id) => templates.firstWhere((t) => t.id == id);

  factory ExerciseLibrary.fromJson(
    Map<String, dynamic> exercisesJson,
    Map<String, dynamic> templatesJson,
  ) => ExerciseLibrary(
    [
      for (final e in exercisesJson['exercises'] as List)
        Exercise.fromJson(Map<String, dynamic>.from(e as Map)),
    ],
    [
      for (final t in templatesJson['templates'] as List)
        PlanTemplate.fromJson(Map<String, dynamic>.from(t as Map)),
    ],
  );

  static Future<ExerciseLibrary> load() async {
    final ex = await rootBundle.loadString('assets/library/exercises.json');
    final tp = await rootBundle.loadString('assets/library/templates.json');
    return ExerciseLibrary.fromJson(
      jsonDecode(ex) as Map<String, dynamic>,
      jsonDecode(tp) as Map<String, dynamic>,
    );
  }
}
